// Returns the referral_drafts contacts for (auth_user_id, job_id), sorted by score.
const q = $('Webhook GET job-referral').first().json.query || {};
const authUserId = String(q.auth_user_id ?? '').trim();
const jobId = String(q.job_id ?? '').trim();

if (!authUserId || !jobId) {
  return [{ json: { success: false, error: !authUserId ? 'missing_auth_user_id' : 'missing_job_id', auth_user_id: authUserId || null, job_id: jobId || null, contacts_count: 0, contacts: [] } }];
}

const rows = $('Find Referral Drafts').all().map(i => i.json).filter(r => r && r.job_id);
if (rows.length === 0) {
  return [{ json: { success: true, auth_user_id: authUserId, job_id: jobId, job_title: null, company: null, job_url: null, status: 'not_generated', contacts_count: 0, contacts: [] } }];
}

const first = rows[0];
const contacts = [];
for (const r of rows) {
  // marker row written by Referals when no contacts were found for this job
  if (r.status === 'no_contacts' && !r.contact_linkedin_url && !r.contact_name) continue;
  contacts.push({
    draft_id: r.id,
    contact_name: r.contact_name || null,
    contact_linkedin_url: r.contact_linkedin_url || null,
    contact_headline: r.contact_headline || null,
    tier: r.tier || null,
    score: r.score ?? 0,
    match_reasons: String(r.match_reasons || '').split('; ').filter(Boolean),
    email: r.email || null,
    email_status: r.email_status || null,
    channel: r.channel || null,
    subject: r.subject || null,
    body: r.body || null,
    linkedin_note: r.linkedin_note || null,
    gmail_draft_id: r.gmail_draft_id || null,
    status: r.status || null,
  });
}
contacts.sort((a, b) => (b.score ?? 0) - (a.score ?? 0));

return [{ json: {
  success: true,
  auth_user_id: authUserId,
  job_id: jobId,
  job_title: first.job_title || null,
  company: first.company || null,
  job_url: first.job_url || null,
  status: contacts.length > 0 ? 'drafted' : 'no_contacts',
  contacts_count: contacts.length,
  contacts,
} }];
